package com.langfundamentals;

public class primitivedatatypes {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		byte age = 21;
		short students = 5000;
		int annualsalary = 1200000;
		long population = 1400000000000l;
		float percentage = 82.1f;
		double bankbalance = 30567.98;
		char grade = 'A';
		boolean javalearner = true;
		
		
		System.out.println("Age: "+age);
		System.out.println("no.of students: "+ students);
		System.out.println("annual salary: "+annualsalary);
		System.out.println("population: "+population);
		System.out.println("percentage: "+percentage);
		System.out.println("bankbalance: "+bankbalance);
		System.out.println("grade: "+grade);
		System.out.println("javalearner: "+javalearner);
		
		
	}

}


